"""Generate docs/cli.md from the argparse definitions in gxbake.cli.

	python -m gxbake.clidoc            # rewrite docs/cli.md
	python -m gxbake.clidoc --check    # exit 1 if it is out of date (the tests do this)
"""

from __future__ import annotations

import argparse
import re
import sys
from pathlib import Path

DOC = Path(__file__).resolve().parent.parent / "docs" / "cli.md"

INTRO = """# GxBake command line reference

<!-- Generated by `python -m gxbake.clidoc` from gxbake/cli.py. Do not edit by hand. -->

Every command the `gxbake` executable (or `python -m gxbake`) accepts. Run with no
command, or with file paths, it opens the desktop app instead. For how the commands
fit together when porting a game, see [the porting workflow](workflow.md).

Sizes such as `448K`, `1.5M` or `6MiB` are accepted wherever an option takes a size.
Commands that check something exit with 1 when the check fails, so they can gate a
build or CI job.
"""


def _sub(parser: argparse.ArgumentParser):
	return next((a for a in parser._actions if isinstance(a, argparse._SubParsersAction)), None)


def _flags(a: argparse.Action) -> str:
	if not a.option_strings:
		name = a.metavar or a.dest
		return f"`{name}`" + (" …" if a.nargs in ("+", "*") else "")
	metavar = ""
	if a.nargs != 0:
		metavar = " " + (a.metavar or (a.dest.upper() if not a.choices else "{" + ",".join(map(str, a.choices)) + "}"))
	return ", ".join(f"`{o}{metavar}`" for o in a.option_strings)


def _default(a: argparse.Action) -> str:
	if a.nargs == 0 or a.default in (None, argparse.SUPPRESS, False) or a.required or not a.option_strings:
		return ""
	return f"`{a.default}`"


def _help(a: argparse.Action) -> str:
	text = re.sub(r"'([^' ]+)'", r"`\1`", (a.help or "").replace("|", "\\|"))
	if a.option_strings and a.required:
		text = ("**Required.** " + text).strip()
	if a.option_strings and isinstance(a, argparse._AppendAction):
		text += "" if "repeatable" in text else " (repeatable)"
	return text.strip()


def _usage(name: str, parser: argparse.ArgumentParser) -> str:
	"""Usage line built here rather than by argparse, whose formatting differs between Python versions."""
	import textwrap

	parts = []
	for a in parser._actions:
		if isinstance(a, argparse._HelpAction) or a.help == argparse.SUPPRESS:
			continue
		if isinstance(a, argparse._SubParsersAction):
			parts.append((a.metavar or "command") + " ...")
		elif a.option_strings:
			flag = a.option_strings[-1]
			if a.nargs != 0:
				flag += " " + (a.metavar or (a.dest.upper() if not a.choices else "{" + ",".join(map(str, a.choices)) + "}"))
			parts.append(flag if a.required else f"[{flag}]")
		else:
			m = a.metavar or a.dest
			parts.append({"+": f"{m} [{m} ...]", "*": f"[{m} ...]", "?": f"[{m}]"}.get(a.nargs, m))
	return textwrap.fill(" ".join([name, *parts]), 100, subsequent_indent="    ", break_on_hyphens=False, break_long_words=False)


def _section(name: str, parser: argparse.ArgumentParser, help_text: str, level: int, out: list[str]) -> None:
	out.append(f"{'#' * level} `{name}`")
	out.append("")
	desc = parser.description or help_text
	if desc:
		out.append(desc[0].upper() + desc[1:] + ("" if desc.endswith(".") else "."))
		out.append("")
	out.append("```")
	out.append(_usage(name, parser))
	out.append("```")
	out.append("")
	rows = [a for a in parser._actions
		if not isinstance(a, (argparse._HelpAction, argparse._SubParsersAction)) and a.help != argparse.SUPPRESS]
	if rows:
		out.append("| Argument | Default | Description |")
		out.append("| --- | --- | --- |")
		for a in rows:
			out.append(f"| {_flags(a)} | {_default(a)} | {_help(a)} |")
		out.append("")
	sub = _sub(parser)
	if sub:
		helps = {c.dest: c.help for c in sub._choices_actions}
		for child, p in sub.choices.items():
			_section(f"{name} {child}", p, helps.get(child, ""), level + 1, out)


def render() -> str:
	from .cli import build_parser

	parser = build_parser()
	out = [INTRO]
	sub = _sub(parser)
	helps = {c.dest: c.help for c in sub._choices_actions}
	out.append("## Commands")
	out.append("")
	out.append("| Command | What it does |")
	out.append("| --- | --- |")
	for name in sub.choices:
		out.append(f"| [`{name}`](#gxbake-{name}) | {helps.get(name, '')} |")
	out.append("")
	for name, p in sub.choices.items():
		_section(f"gxbake {name}", p, helps.get(name, ""), 2, out)
	out += _budget_table()
	return "\n".join(out).rstrip() + "\n"


def _budget_table() -> list[str]:
	from dataclasses import fields

	from .core.audit import human_bytes
	from .core.budget import BUDGET_HELP, Budgets

	b = Budgets()
	out = ["## Budget names", "",
		"The limits `budget` and `fit` check, taken from the Xash3D GameCube port. Change any of them with "
		"`--budget NAME=SIZE` (repeatable), e.g. `--budget studio_arena=1.5M`.", "",
		"| Name | Default | What it limits |", "| --- | --- | --- |"]
	for f in fields(b):
		v = getattr(b, f.name)
		shown = str(v) if f.name in ("wt_split", "wt_max_textures") else f"{human_bytes(v)} ({v:,} bytes)"
		out.append(f"| `{f.name}` | {shown} | {BUDGET_HELP.get(f.name, '')} |")
	out.append("")
	return out


def main(argv: list[str] | None = None) -> int:
	argv = sys.argv[1:] if argv is None else argv
	text = render()
	if "--check" in argv:
		if not DOC.is_file() or DOC.read_text() != text:
			print("docs/cli.md is out of date; run: python -m gxbake.clidoc", file=sys.stderr)
			return 1
		return 0
	DOC.parent.mkdir(exist_ok=True)
	DOC.write_text(text)
	print(f"wrote {DOC}")
	return 0


if __name__ == "__main__":
	raise SystemExit(main())
